import{_ as t,o as a,c as n,aw as l}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Объект события (Event)","description":"","frontmatter":{},"headers":[],"relativePath":"js/js-web-api/dom-events/params-event.md","filePath":"wiki/dev-commit/js/js-web-api/dom-events/params-event.md"}'),o={name:"js/js-web-api/dom-events/params-event.md"};function s(c,e,i,r,p,d){return a(),n("div",null,[...e[0]||(e[0]=[l(`<h1 id="объект-события-event" tabindex="-1">Объект события (Event) <a class="header-anchor" href="#объект-события-event" aria-label="Permalink to &quot;Объект события (Event)&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Event</strong> - объект созданный перед запуском события</li></ul></div><ul><li>Когда происходит событие, браузер создаёт объект события, записывает в него детали и передаёт его в качестве аргумента функции-обработчику</li></ul><div class="language-js"><button title="Скопировать код" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> btn</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> document.</span><span style="color:#4078F2;">getElementById</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;btn&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">btn.</span><span style="color:#4078F2;">addEventListener</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;click&quot;</span><span style="color:#383A42;">, (event) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(event));</span></span></code></pre></div><h2 id="объект-события-event-1" tabindex="-1">Объект события (Event) <a class="header-anchor" href="#объект-события-event-1" aria-label="Permalink to &quot;Объект события (Event)&quot;">​</a></h2><h3 id="возвращает-объект-данные" tabindex="-1">Возвращает объект/данные <a class="header-anchor" href="#возвращает-объект-данные" aria-label="Permalink to &quot;Возвращает объект/данные&quot;">​</a></h3><ul><li><code>event.type</code> - название события (н-р click)</li><li><code>event.target</code> - инициатор события</li><li><code>event.currentTarget</code> - элемент на котором сработал обработчик. Значение – обычно такое же, как и у this, но если обработчик является функцией-стрелкой или при помощи bind привязан другой объект в качестве this, то мы можем получить элемент из event.currentTarget</li><li><code>event.eventPhase</code> - номер фазы, на которой событие было поймано (Event.CAPTURING_PHASE=1, Event.AT_TARGET=2, Event.BUBBLING_PHASE=3)</li><li><code>event.timeStamp</code> - число (миллисекунды, DOMHighResTimeStamp), указывающее, когда произошло событие</li><li><code>event.bubbles</code> - true если событие может всплывать по дереву элементов. События blur, focus, load, unload не всплывают</li><li><code>event.cancelable</code> - true если с этим событием связано действие по умолчанию и его можно отменить preventDefault</li><li><code>event.clientX</code> - координата X курсора в момент клика относительно окна, для событий мыши</li><li><code>event.clientY</code> - координата Y курсора в момент клика относительно окна, для событий мыши</li></ul><h3 id="методы" tabindex="-1">Методы <a class="header-anchor" href="#методы" aria-label="Permalink to &quot;Методы&quot;">​</a></h3><ul><li><code>event.preventDefault()</code> - отключение действия события по умолчанию</li><li><code>event.stopPropagation()</code> - прекращение всплытия</li><li><code>event.stopImmediatePropagation()</code> - прекращение всплытия и остановка обработки событий на текущем элементе</li></ul>`,10)])])}const h=t(o,[["render",s]]);export{u as __pageData,h as default};
